use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
# [doc = " Generate workspace Cargo.toml with members and dependencies"] pub fn generate_workspace_toml (members : & [String] , dependencies : & HashMap < String , Value > , output_path : & Path ,) -> Result < () > { let mut content = String :: new () ; content . push_str ("[workspace]\nresolver = \"2\"\nmembers = [\n") ; for member in members { content . push_str (& format ! ("    \"{}\",\n" , member)) ; } content . push_str ("]\n\n[workspace.dependencies]\n") ; for (name , value) in dependencies { content . push_str (& format ! ("{} = {}\n" , name , value)) ; } let header = format ! ("# Generated by lib-cargo workspace generator\n# Do not edit this file by hand. Your changes will be overwritten.\n\n") ; let final_content = header + & content ; std :: fs :: write (output_path , final_content) ? ; Ok (()) }
}